INSERT INTO tbl_faqs (uniqueid, question, answer, home, ip, status, created_at, updated_at) SELECT CONCAT(FLOOR(10 + RAND()*91), SUBSTRING(MD5(RAND()), 1, 13)), 'You are present in which all cities in India and abroad?', 'In India, we are present in Gurgaon (Delhi NCR) , Bangalore and Mumbai. Other than this, we have centers in Malaysia, Philippines, Indonesia &amp; Singapore.', 0, NULL, 1, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tbl_faqs WHERE question = 'You are present in which all cities in India and abroad?');
INSERT INTO tbl_faqs (uniqueid, question, answer, home, ip, status, created_at, updated_at) SELECT CONCAT(FLOOR(10 + RAND()*91), SUBSTRING(MD5(RAND()), 1, 13)), 'Which center is better - Gurgaon or Bangalore or Mumbai?', 'All our centers across Asia are company owned and similar in terms of infrastructure, Faculty, Course Material and Facilities. In fact, the faculties keep getting rotated across three centers. There is absolutely no difference and hence you can study in any center of ours with a complete assurance of quality from us.', 0, NULL, 1, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tbl_faqs WHERE question = 'Which center is better - Gurgaon or Bangalore or Mumbai?');
INSERT INTO tbl_faqs (uniqueid, question, answer, home, ip, status, created_at, updated_at) SELECT CONCAT(FLOOR(10 + RAND()*91), SUBSTRING(MD5(RAND()), 1, 13)), 'I want to study in your Malaysia Centre. How do I go about it?', 'Malaysia Government currently does not give visa for such short courses. However, if you can arrange the visa on your own, you are most welcome to study with us in our Malaysia center.', 0, NULL, 1, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tbl_faqs WHERE question = 'I want to study in your Malaysia Centre. How do I go about it?');
INSERT INTO tbl_faqs (uniqueid, question, answer, home, ip, status, created_at, updated_at) SELECT CONCAT(FLOOR(10 + RAND()*91), SUBSTRING(MD5(RAND()), 1, 13)), 'What kind of courses do you offer?', 'We offer specialization in two major discipline of food: Culinary and Patisserie. The courses are Full Time and Part Time. Which course will suit you depends on whether you want to learn to make a career in it or just for the hobby. The full-time course is meant for people who want to work for 5-star hotels, leading restaurants and bakeries or who want to open their own venture. Part -Time is meant for those who want to learn it as a hobby.', 0, NULL, 1, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tbl_faqs WHERE question = 'What kind of courses do you offer?');
INSERT INTO tbl_faqs (uniqueid, question, answer, home, ip, status, created_at, updated_at) SELECT CONCAT(FLOOR(10 + RAND()*91), SUBSTRING(MD5(RAND()), 1, 13)), 'I want to become a professional chef. Which course will suit me?', 'We would recommend you Advance Diploma program which is of 1 year. It includes 9 months hands-on training in India center followed by 3 to 6 months of internship. The course is very intense and each student gets enough practice hours. You can choose either our culinary course or pastry/ bakery course.. Students who have just completed class 12th can also take a 3 year program. This 3 year covers both Pastry, Baking &amp; Culinary. In the 3rd year students gets opportunity for the international internships.', 0, NULL, 1, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tbl_faqs WHERE question = 'I want to become a professional chef. Which course will suit me?');
INSERT INTO tbl_faqs (uniqueid, question, answer, home, ip, status, created_at, updated_at) SELECT CONCAT(FLOOR(10 + RAND()*91), SUBSTRING(MD5(RAND()), 1, 13)), 'I want to learn food only for hobby. Would Part Time suit me?', 'You are right. Weekend or Part Time course is meant for people who want to learn it for hobby or for working professionals who do not have time to pursue our Full-Time Course', 0, NULL, 1, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tbl_faqs WHERE question = 'I want to learn food only for hobby. Would Part Time suit me?');
INSERT INTO tbl_faqs (uniqueid, question, answer, home, ip, status, created_at, updated_at) SELECT CONCAT(FLOOR(10 + RAND()*91), SUBSTRING(MD5(RAND()), 1, 13)), 'Do you teach eggless baking? Is your course vegetarian?', 'We follow French cuisines and eggs are used in most of our recipes. Although we have one module of eggless in our Advance diploma program. Chicken is used in very limited recipes and the students are free to learn/ prepare only the vegetarian options.', 0, NULL, 1, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tbl_faqs WHERE question = 'Do you teach eggless baking? Is your course vegetarian?');
INSERT INTO tbl_faqs (uniqueid, question, answer, home, ip, status, created_at, updated_at) SELECT CONCAT(FLOOR(10 + RAND()*91), SUBSTRING(MD5(RAND()), 1, 13)), 'Can I pay in installments?', 'Yes, we do have installment options available. You can contact us for more details.', 0, NULL, 1, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tbl_faqs WHERE question = 'Can I pay in installments?');
INSERT INTO tbl_faqs (uniqueid, question, answer, home, ip, status, created_at, updated_at) SELECT CONCAT(FLOOR(10 + RAND()*91), SUBSTRING(MD5(RAND()), 1, 13)), 'How do I pay my fees?', 'You can pay by cheque, bank transfer, credit card.', 0, NULL, 1, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tbl_faqs WHERE question = 'How do I pay my fees?');
INSERT INTO tbl_faqs (uniqueid, question, answer, home, ip, status, created_at, updated_at) SELECT CONCAT(FLOOR(10 + RAND()*91), SUBSTRING(MD5(RAND()), 1, 13)), 'Tell us more about this course?', 'This is a one week intensive course and offered at an attractive fee to our students. We offer the course to our students who finish the Advance Diploma in Pastry and Bakery with us(Travel and accommodation are included).', 0, NULL, 1, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tbl_faqs WHERE question = 'Tell us more about this course?');
INSERT INTO tbl_faqs (uniqueid, question, answer, home, ip, status, created_at, updated_at) SELECT CONCAT(FLOOR(10 + RAND()*91), SUBSTRING(MD5(RAND()), 1, 13)), 'What is the benefit of this course?', 'The students get a chance to interact with international students of various nationalities and compare their skill levels with them. The faculty who teaches are likes of World Pastry Champions and various international award winners, etc', 0, NULL, 1, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tbl_faqs WHERE question = 'What is the benefit of this course?');
INSERT INTO tbl_faqs (uniqueid, question, answer, home, ip, status, created_at, updated_at) SELECT CONCAT(FLOOR(10 + RAND()*91), SUBSTRING(MD5(RAND()), 1, 13)), 'How much will the course cost and what does it include?', 'The total cost is Rs 1,50,000 all inclusive. This includes a 6 days hands on master class, flight tickets, accommodation in a luxury 4 star hotel for 7 nights inclusive breakfast, airport transfers, 2 complimentary dinners and one day universal studio pass with lunch.', 0, NULL, 1, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tbl_faqs WHERE question = 'How much will the course cost and what does it include?');
INSERT INTO tbl_faqs (uniqueid, question, answer, home, ip, status, created_at, updated_at) SELECT CONCAT(FLOOR(10 + RAND()*91), SUBSTRING(MD5(RAND()), 1, 13)), 'Who will take our classes?', 'All our chef faculty has worked with 5-star hotels like Oberoi, Taj, Novotel, ITC, etc. They all are now working with the academy full time. These chefs have attended numerous Master Classes with World Champions, MOFs and other Master Chefs and have won various national and international competitions.', 0, NULL, 1, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tbl_faqs WHERE question = 'Who will take our classes?');
INSERT INTO tbl_faqs (uniqueid, question, answer, home, ip, status, created_at, updated_at) SELECT CONCAT(FLOOR(10 + RAND()*91), SUBSTRING(MD5(RAND()), 1, 13)), 'Tell us a little more about your chef faculty?', 'At this moment, we have 20+ chef faculties. Most of our other chefs were handpicked by hotels for their management trainee program like TMTP, OCLD, ITC School of Management. After working with them for few years, they are now working as Full-Time Faculty in the academy. It is noteworthy that they have won various National and International competitions like Asian Pastry Cup - Singapore, India Pastry Cup 2015, India Pastry Cup 2017, India Pastry Cup 2020, Pastry Queen India, Junior Pastry Cup twice. They have also represented India on various International platforms like World Pastry Cup-France, Junior Pastry World Cup-Italy, and Ladies Pastry Cup- Italy. Our faculty members from Malaysia academy have also won the World Pastry Cup 2019.', 0, NULL, 1, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tbl_faqs WHERE question = 'Tell us a little more about your chef faculty?');
INSERT INTO tbl_faqs (uniqueid, question, answer, home, ip, status, created_at, updated_at) SELECT CONCAT(FLOOR(10 + RAND()*91), SUBSTRING(MD5(RAND()), 1, 13)), 'When will the next batch begin?', 'We have 4 intakes in a year, starts every 3 months. The details about the next intake are available on our website and various social media channels.', 0, NULL, 1, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tbl_faqs WHERE question = 'When will the next batch begin?');
INSERT INTO tbl_faqs (uniqueid, question, answer, home, ip, status, created_at, updated_at) SELECT CONCAT(FLOOR(10 + RAND()*91), SUBSTRING(MD5(RAND()), 1, 13)), 'What is the requirement to get admission and what is the eligibility required to join?', 'For the Advance Diploma program , a student should be minimum 16 years of age and have basic knowledge of English. There is no maximum age limit. For the UG 3 Year program student must have cleared class 12th from a recognized board.', 0, NULL, 1, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tbl_faqs WHERE question = 'What is the requirement to get admission and what is the eligibility required to join?');
INSERT INTO tbl_faqs (uniqueid, question, answer, home, ip, status, created_at, updated_at) SELECT CONCAT(FLOOR(10 + RAND()*91), SUBSTRING(MD5(RAND()), 1, 13)), 'I do not know anything about food or baking. Can I take admission?', 'Absolutely. We expect our students to be raw with no knowledge of food/ baking. We start from the basic and no prior knowledge in food or Baking is required.', 0, NULL, 1, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tbl_faqs WHERE question = 'I do not know anything about food or baking. Can I take admission?');
INSERT INTO tbl_faqs (uniqueid, question, answer, home, ip, status, created_at, updated_at) SELECT CONCAT(FLOOR(10 + RAND()*91), SUBSTRING(MD5(RAND()), 1, 13)), 'Will I get an internship after the course?', 'Yes, we have tied up with leading hotels/ bakeries/ Restaurants for the internship. We recommend all students to undergo internship even if they want to open their own venture. Our students also have opportunity to take up internships in France.', 0, NULL, 1, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tbl_faqs WHERE question = 'Will I get an internship after the course?');
INSERT INTO tbl_faqs (uniqueid, question, answer, home, ip, status, created_at, updated_at) SELECT CONCAT(FLOOR(10 + RAND()*91), SUBSTRING(MD5(RAND()), 1, 13)), 'Will you guys assist in Job Placement?', 'Yes, we do assist in jobs. In fact, our students are in high demand since they have undergone hands-on training and can be effective on the day 1 in the kitchen.', 0, NULL, 1, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tbl_faqs WHERE question = 'Will you guys assist in Job Placement?');
INSERT INTO tbl_faqs (uniqueid, question, answer, home, ip, status, created_at, updated_at) SELECT CONCAT(FLOOR(10 + RAND()*91), SUBSTRING(MD5(RAND()), 1, 13)), 'Which hotels/ Restaurants/ Bakery do you have a tie-up with?', 'Our students have interned/ are working with leading 5-star hotels and leading bakeries Oberoi, Taj, ITC, Leela, Novotel, Holiday Inn, The Fishermen Wharf, Theos, Theobroma, Lâ Opera, La Folie, etc. some of our students have also working abroad . Our students also get opportunity to work with International cruise lines.', 0, NULL, 1, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tbl_faqs WHERE question = 'Which hotels/ Restaurants/ Bakery do you have a tie-up with?');
INSERT INTO tbl_faqs (uniqueid, question, answer, home, ip, status, created_at, updated_at) SELECT CONCAT(FLOOR(10 + RAND()*91), SUBSTRING(MD5(RAND()), 1, 13)), 'Will your institute help in bank education loan?', 'Most of the banks will be happy to help you in education loan. Please write to us in case you need any help from us.', 0, NULL, 1, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tbl_faqs WHERE question = 'Will your institute help in bank education loan?');
INSERT INTO tbl_faqs (uniqueid, question, answer, home, ip, status, created_at, updated_at) SELECT CONCAT(FLOOR(10 + RAND()*91), SUBSTRING(MD5(RAND()), 1, 13)), 'Are you affiliated with any university or government body?', 'We are approved center of City &amp; Guilds UK, so all the certification is given to the student on completion of the course by City &amp; Guilds UK .', 0, NULL, 1, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tbl_faqs WHERE question = 'Are you affiliated with any university or government body?');
INSERT INTO tbl_faqs (uniqueid, question, answer, home, ip, status, created_at, updated_at) SELECT CONCAT(FLOOR(10 + RAND()*91), SUBSTRING(MD5(RAND()), 1, 13)), 'How much fee I have to pay for City & Guilds Exam?', 'Currently they charge between Rs 15,500-17,500 + 18% GST for level 2 and around Rs 20,000 + 18% GST for level 3. The fee is subject to revision by the C&amp;G authorities', 0, NULL, 1, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tbl_faqs WHERE question = 'How much fee I have to pay for City & Guilds Exam?');
INSERT INTO tbl_faqs (uniqueid, question, answer, home, ip, status, created_at, updated_at) SELECT CONCAT(FLOOR(10 + RAND()*91), SUBSTRING(MD5(RAND()), 1, 13)), 'Any other affiliation with a government body?', 'We are also affiliated with THSC (Tourism and Hospitality Skill Council) which is government recognized body and we conduct examinations for the same.', 0, NULL, 1, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tbl_faqs WHERE question = 'Any other affiliation with a government body?');
INSERT INTO tbl_faqs (uniqueid, question, answer, home, ip, status, created_at, updated_at) SELECT CONCAT(FLOOR(10 + RAND()*91), SUBSTRING(MD5(RAND()), 1, 13)), 'Is it mandatory to appear for the C&G exam?', 'It is not mandatory to appear for the C&amp; exam. However, it is strongly recommended since the benefits are unparalleled.', 0, NULL, 1, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tbl_faqs WHERE question = 'Is it mandatory to appear for the C&G exam?');
INSERT INTO tbl_faqs (uniqueid, question, answer, home, ip, status, created_at, updated_at) SELECT CONCAT(FLOOR(10 + RAND()*91), SUBSTRING(MD5(RAND()), 1, 13)), 'What happens to the product that we make in our class?', 'All the products are divided equally between the class and students are allowed to take them home. We want you to spread your happiness among your parents, friends, neighbors, relatives and anybody who is happy with your progress. We also encourage our students to share their products with under privileged kids as well.', 0, NULL, 1, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tbl_faqs WHERE question = 'What happens to the product that we make in our class?');
INSERT INTO tbl_faqs (uniqueid, question, answer, home, ip, status, created_at, updated_at) SELECT CONCAT(FLOOR(10 + RAND()*91), SUBSTRING(MD5(RAND()), 1, 13)), 'Will there be a break in 9 months course?', 'Yes, break is given around major festivals of India basis the region of that center.', 0, NULL, 1, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tbl_faqs WHERE question = 'Will there be a break in 9 months course?');
